-- composition of rule kernels L:eliminate_cross_join x L:eliminate_join (datafusion), template cte_twice
WITH ka AS (WITH cte1 AS (SELECT ARRAY['1'::text] AS c0, '2000-01-01 00:00:00+00'::timestamptz AS c1, a1.c0 AS c2 FROM tp AS a1, generate_series (10, 5) AS a2 (c0) WHERE (a2.c0 > a1.c0) GROUP BY ROLLUP (a1.c0)) SELECT '_'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2 INTERSECT SELECT '[1,10)'::text AS c0, 0::bigint AS c1, (NULL::bigint + 10::bigint) AS c2 FROM cte1 AS a3 GROUP BY a3.c2), kb AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a2.c1 AS c0, a1.c1 AS c1 FROM (ti AS a1 JOIN (t2 AS a2 JOIN v0 AS a3 ON (a2.c0 = a3.n)) ON ((a1.c0 = a3.c0) AND FALSE))) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH cte1 AS (SELECT ARRAY['1'::text] AS c0, '2000-01-01 00:00:00+00'::timestamptz AS c1, a1.c0 AS c2 FROM tp AS a1, generate_series (10, 5) AS a2 (c0) WHERE (a2.c0 > a1.c0) GROUP BY ROLLUP (a1.c0)) SELECT '_'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2 INTERSECT SELECT '[1,10)'::text AS c0, 0::bigint AS c1, (NULL::bigint + 10::bigint) AS c2 FROM cte1 AS a3 GROUP BY a3.c2) AS ka) + (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a2.c1 AS c0, a1.c1 AS c1 FROM (ti AS a1 JOIN (t2 AS a2 JOIN v0 AS a3 ON (a2.c0 = a3.n)) ON ((a1.c0 = a3.c0) AND FALSE))) AS kb)
